fn solve(s: &Vec<char>) -> Vec<char> {
    // Create a mutable copy of the input
    let mut result = s.clone();

    // Check the last character and append the appropriate suffix
    if let Some(&last_char) = s.last() {
        if last_char == 's' {
            result.push('e');
            result.push('s');
        } else {
            result.push('s');
        }
    }

    result
}

fn main() {
    // Some example usages
    let word1: Vec<char> = "dog".chars().collect();
    let word2: Vec<char> = "bus".chars().collect();
    let word3: Vec<char> = "glass".chars().collect();

    let plural1 = solve(&word1);
    let plural2 = solve(&word2);
    let plural3 = solve(&word3);

    println!("{}", plural1.iter().collect::<String>()); // "dogs"
    println!("{}", plural2.iter().collect::<String>()); // "buses"
    println!("{}", plural3.iter().collect::<String>()); // "glasses"
}